module.exports = {
  up: async () => {
    const saltRounds = parseInt(process.env.BCRYPT_SALT_ROUNDS, 10) || 12;

    for (const account of DEMO_ACCOUNTS) {
      const authorizedUser = await AuthorizedUser.create({
        email: account.email,
        fullName: account.fullName,
        role: account.role,
        department: account.department,
        isActive: account.isActive,
      });

      if (account.isActive) {
        const passwordHash = await bcrypt.hash(account.password, saltRounds);
        await User.create({
          authorizedUserId: authorizedUser.id,
          email: account.email,
          passwordHash,
          role: account.role, // copied from the authorized-list record, same rule as real registration
          isAdmin: false,
        });
      }
    }
  },

  down: async () => {
    const emails = DEMO_ACCOUNTS.map((a) => a.email);
    await User.destroy({ where: { email: emails } });
    await AuthorizedUser.destroy({ where: { email: emails } });
  },
};
